          if((amzp_bloxx>0.5)) { p.z -= 6.0 + iTime * 6.0; }
          d = min(d, dot(p, normalize(sign(p))) - 1.0);
          g += 0.015 / (0.01 + d * d);
          return d;
         }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float2 iMouse = float2(0.5, 0.5);
        float iTime = (amzp_autop>0.5)? amzp_PROGRESS + (time*amzp_SPEED) : amzp_PROGRESS;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((0.0+amzp_angle)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.0,1.0)/500.0;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
          float2 uv = satriyaid;
          float dt = iTime * 6.0;
          float3 ro = float3(0, 0, -5.0 + dt);
          float3 ta = float3(amzp_CAM.x, amzp_CAM.y, dt);
          ro.xy += path(ro.z);
          ta.xy += path(ta.z);
          float3 fwd = normalize(ta - ro);
          float3 right = cross(fwd, float3(0, 1, 0));
          float3 up = cross(right, fwd);
          float3 rd = normalize(fwd + uv.x*right + uv.y*up);
          rd.xy *= r2d(sin(-ro.x / 3.14)*0.3);
          float3 p = floor(ro) + 0.5;
          float3 mask;
          float3 drd = 1.0 / abs(rd);
          rd = sign(rd);
          float3 side = drd * (rd * (p - ro) + 0.5);
          float t = 0.0, ri = 0.0;
          for (float i = 0.0; i < 1.0; i += 0.01) {
           ri = i;
           if (de(p) < 0.0) break;
           mask = step(side, side.yzx) * step(side, side.zxy);
           side += drd * mask;
           p += rd * mask;
          }
          t = length(p - ro);
          float3 c = float3(1) * length(mask * float3(amzp_color1.rgb));
          c = mix(float3(amzp_color2.rgb), float3(amzp_color3.rgb), c);
          c += g * amzp_GAM;
                   if( int(amzp_CHAN)==0 ) { c.r += sin(iTime)*0.2 + sin(p.z*0.5 - iTime * 6.0); }
                   else if( int(amzp_CHAN)==1 ) { c.g += sin(iTime)*0.2 + sin(p.z*0.5 - iTime * 6.0); }
                   else if( int(amzp_CHAN)==2 ) { c.b += sin(iTime)*0.2 + sin(p.z*0.5 - iTime * 6.0); }
          c = mix(c, float3(amzp_color4.rgb), 1.0 - exp(-0.001*t*t));
          fragColor = float4(c, 1.0);
           float4 factor = mix(texColorX,fragColor,1.0);
        float4 resultfinal;
          if( int(amzp_blendMode)==0 ) { resultfinal = (factor * amzp_hardness) * texColor.a; }
          else if( int(amzp_blendMode)==1 ) { factor *= amzp_hardness;
            float4 c = factor + float4(1.0)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
          else if( int(amzp_blendMode)==2 ) { factor *= amzp_hardness;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
          else if( int(amzp_blendMode)==3 ) { factor *= amzp_hardness; resultfinal = (newLayer(texColor, factor) * amzp_hardness) * texColor.a; }
     amzOutput = mix(texColor, resultfinal, amzp_alpha) * texColor.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
